from construire import Chapter,fig,box,qs,sub
from figures_communes import common,plot
from math import sqrt,pi,exp,log

def create():
 c=Chapter(5,'Oscillations libres amorties','1.4 / régimes transitoires du deuxième ordre','les régimes libres et les réponses à un échelon des oscillateurs amortis, électriques et mécaniques, ainsi que leur identification expérimentale.')
 common(c)
 plot(c,'regimes',[('exp(-0.25*x)*(cos(deg(0.96824584*x))+0.25819889*sin(deg(0.96824584*x)))','Q = 2','otNavy'),('(1+x)*exp(-x)','Q = 0,5','otGreenDark'),('1.07735027*exp(-0.26794919*x)-0.07735027*exp(-3.73205081*x)','Q = 0,25','otOrange')],xmax=16,ymin=-.55,ymax=1.1,xlabel=r'$\omega_0t$',ylabel='$x/x_0$')
 plot(c,'amorti',[('exp(-0.2*x)*(cos(deg(0.979795897*x))+0.204124145*sin(deg(0.979795897*x)))','Réponse exacte','otNavy'),('1.020620726*exp(-0.2*x)','Enveloppe supérieure','otGreenDark'),('-1.020620726*exp(-0.2*x)','Enveloppe inférieure','otGreenDark')],xmax=22,xlabel=r'$\omega_0t$',ylabel='$x/x_0$')
 plot(c,'echelon',[('1-exp(-0.25*x)*(cos(deg(0.96824584*x))+0.25819889*sin(deg(0.96824584*x)))','Q = 2','otNavy'),('1-(1+x)*exp(-x)','Q = 0,5','otGreenDark')],xmax=16,ymin=0,ymax=1.55,xlabel=r'$\omega_0t$',ylabel='$x/x_e$')
 c.f('spirale',r'''\draw[axis](-3,0)--(3.2,0)node[right]{$x/x_0$};\draw[axis](0,-2.6)--(0,2.6)node[above]{$v/(\omega_0x_0)$};\draw[otNavy,thick,domain=0:20,samples=350]plot({2.5*exp(-.12*\x)*(cos(deg(.99277389*\x))+.12087344*sin(deg(.99277389*\x)))},{-2.5/.99277389*exp(-.12*\x)*sin(deg(.99277389*\x))});\draw[-{Stealth},otGreenDark,thick](2.5,0)--(2.48,-.45);\node[lab,text width=4cm,align=left]at(7,1){L’énergie diminue.\\La trajectoire s’enroule vers l’équilibre.\\Le point initial a une vitesse nulle.};''')
 c.intro="Dans une expérience réelle, les oscillations s’atténuent ou disparaissent. L’équation du deuxième ordre permet de relier cette évolution aux pertes, de prévoir les dépassements et de mesurer un amortissement à partir d’un enregistrement."
 c.mapping=r"Mettre l’équation sous forme canonique et identifier $\omega_0$ et Q ; prévoir la nature de la réponse. Résoudre un régime libre ou un échelon à l’aide des racines caractéristiques. Estimer les durées selon Q, faire le bilan énergétique et comparer les oscillateurs mécanique et électrique. Acquérir et analyser un transitoire."
 c.prereq=r"Chapitre 04 : oscillateur harmonique et conditions initiales. Chapitre 02 : conventions et énergies. Équation caractéristique du second degré ; dérivation des exponentielles et fonctions trigonométriques."
 c.method="Établir l’équation et fixer le nouvel équilibre ; poser l’écart à cet équilibre ; identifier la forme canonique ; choisir le régime avec Q ; utiliser les deux conditions initiales et vérifier l’énergie."
 c.boundary="Pages internes 15 et 16 (pages PDF 52 et 53), partie transitoire de la rubrique 1.4. Les impédances et la résonance sinusoïdale sont réservées au chapitre 06."
 c.diagnostic=qs(r"Résoudre $r^2+6r+25=0$ et interpréter partie réelle et partie imaginaire.",r"Dériver $x=e^{-\alpha t}(A\cos\omega t+B\sin\omega t)$ à t = 0.",r"Pour une masse soumise à $F_f=-bv$, donner la puissance de frottement.",r"Donner l’équation d’un RLC série libre en tension uC avec $i=C\dot u_C$.",r"Pourquoi faut-il deux conditions initiales ? Quelles grandeurs sont continues dans le RLC ?",r"Dans $\ddot x+4\dot x+100x=0$, donner la pulsation propre et le coefficient 2α.",r"Une énergie décroissante implique-t-elle nécessairement une position monotone ?",r"Distinguer une période propre et une pseudo-période.")
 c.diag_sol=sub('D1 et D2',r"Les racines sont $-3\pm4i$ ; la partie réelle négative donne la décroissance et la partie imaginaire la pseudo-pulsation. x(0) = A et $\dot x(0)=-\alpha A+\omega B$.")+sub('D3 et D4',r"$P_f=-bv^2\leq0$. Le RLC libre vérifie $LC\ddot u_C+RC\dot u_C+u_C=0$.")+sub('D5 à D8',r"L’ordre deux requiert deux constantes indépendantes. Dans un RLC à excitation non impulsionnelle, uC et iL sont continus, donc uC et sa dérivée le sont. $\omega_0=10$ rad/s et $2\alpha=4$ s$^{-1}$. Une position peut osciller tandis que l’énergie diminue. La pseudo-période est celle des oscillations amorties, différente de $T_0=2\pi/\omega_0$.")
 c.c('Les pertes dans deux réalisations',fig('rlc','R représente ici toute la résistance série, y compris celle de la bobine et du générateur annulé.')+box('loi','Deux équations analogues',r"RLC série libre : $L\ddot q+R\dot q+q/C=0$, avec $i=\dot q$.\par Masse-ressort avec frottement visqueux : $m\ddot x+b\dot x+kx=0$, avec $F_f=-b\dot x$.")+sub('Hypothèses',"Le modèle électrique suppose des composants linéaires et l’ARQS. Le modèle mécanique suppose un frottement proportionnel à la vitesse dans le domaine étudié. Le frottement solide à force de module constant ne conduit pas à cette équation.")+sub('Une analogie qui inclut la dissipation',r"Les correspondances sont $x\leftrightarrow q$, $m\leftrightarrow L$, $k\leftrightarrow1/C$ et $b\leftrightarrow R$. Les deux systèmes perdent leur énergie par une puissance quadratique en vitesse ou en courant.")+box('methode','Quelle résistance dans le calcul ?',"Dans un RLC série, additionner toutes les résistances qui restent dans la boucle après commutation. La résistance affichée sur une boîte n’est pas toujours la résistance totale."))
 c.c('Forme canonique et facteur de qualité',box('loi','Identifier les bons coefficients',r"$\ddot x+(\omega_0/Q)\dot x+\omega_0^2x=0$, avec $\alpha=\omega_0/(2Q)$.\par Mécanique : $\omega_0=\sqrt{k/m}$, $Q=\sqrt{mk}/b$.\par RLC série : $\omega_0=1/\sqrt{LC}$, $Q=\sqrt{L/C}/R$.\par Q est sans dimension ; α se mesure en s$^{-1}$.")+sub('Une lecture physique',r"À paramètres de stockage fixés, augmenter b ou R diminue Q et renforce les pertes. Dans la limite Q très grand, l’évolution se rapproche du modèle harmonique sur quelques oscillations.")+fig('regimes','Même pulsation propre et mêmes conditions x(0) = x0, v(0) = 0 : seul Q change.')+box('piege','La pulsation propre n’est pas la pseudo-pulsation',r"$\omega_0$ vient du coefficient de x dans l’équation. La pulsation observée lorsque le système oscille dépend aussi de l’amortissement."))
 c.c('Trois régimes, un polynôme',box('loi','Racines caractéristiques',r"$r^2+2\alpha r+\omega_0^2=0$.\par Q > 1/2 : $r=-\alpha\pm i\omega_d$, avec $\omega_d=\omega_0\sqrt{1-1/(4Q^2)}$ : régime pseudo-périodique.\par Q = 1/2 : racine double $r=-\omega_0$ : régime critique.\par 0 < Q < 1/2 : deux racines réelles négatives $r_\pm=-\alpha\pm\sqrt{\alpha^2-\omega_0^2}$ : régime apériodique.")+sub('Comment choisir sans calcul inutile',"Mettre d’abord l’équation sous forme canonique ; calculer Q ; choisir alors la forme de solution. Les deux conditions initiales déterminent les coefficients. Des constantes peuvent annuler un mode particulier : les seules racines ne fixent pas toute l’allure.")+fig('regimes','Un régime apériodique est une combinaison de deux exponentielles ; un régime critique comporte aussi un facteur t.')+box('piege','Absence d’oscillation et rapidité',"Un amortissement très fort ne garantit pas un retour rapide. Dans le régime fortement apériodique, une constante lente devient dominante."))
 c.c('La solution pseudo-périodique',box('loi','Deux conditions initiales explicites',r"$x=e^{-\alpha t}[A\cos(\omega_dt)+B\sin(\omega_dt)]$.\par $A=x_0$, $B=(v_0+\alpha x_0)/\omega_d$. Ainsi $\dot x(0)=-\alpha A+\omega_dB=v_0$.")+fig('amorti','Pour une libération sans vitesse, le coefficient du sinus n’est pas nul. Les enveloppes utilisent le module des deux coefficients.')+sub('Libération sans vitesse',r"Avec v0 = 0, $x=x_0e^{-\alpha t}[\cos\omega_dt+(\alpha/\omega_d)\sin\omega_dt]$. Écrire seulement $x_0e^{-\alpha t}\cos\omega_dt$ imposerait une vitesse initiale $-\alpha x_0$, différente de zéro.")+sub('Enveloppe et pseudo-période',r"Le module trigonométrique maximal est $C_0=\sqrt{A^2+B^2}$. On a donc $|x|\leq C_0e^{-\alpha t}$. La pseudo-période vaut $T_d=2\pi/\omega_d$, supérieure à $T_0$."))
 c.c('Le régime critique',box('loi','Une racine double demande deux solutions',r"Pour Q = 1/2 : $x=(A+Bt)e^{-\omega_0t}$, avec $A=x_0$ et $B=v_0+\omega_0x_0$. Pour v0 = 0 : $x=x_0(1+\omega_0t)e^{-\omega_0t}$.")+sub('Pourquoi le facteur t apparaît',r"Deux exponentielles de même racine ne sont pas indépendantes. La seconde solution est $te^{-\omega_0t}$. On peut vérifier directement que les deux satisfont l’équation puis fixer les constantes.")+fig('regimes','La courbe verte correspond au régime critique avec vitesse initiale nulle.')+sub('Une propriété à contextualiser',"Pour un départ sans vitesse depuis un écart donné, le régime critique constitue la limite entre retour sans oscillation et retour oscillant. Il n’est pas nécessaire de transformer cette propriété en affirmation absolue pour toute condition initiale ou tout critère de temps.")+box('methode','Un seuil précis',r"Pour $x_0>0$, v0 = 0 et un seuil de 1 %, résoudre $(1+z)e^{-z}=0{,}01$ avec $z=\omega_0t$. On trouve z ≈ 6,638. La règle $4{,}605/\omega_0$ d’une exponentielle simple ne s’applique pas ici."))
 c.c('Le régime apériodique',box('loi','Deux exponentielles réelles',r"$x=Ae^{r_+t}+Be^{r_-t}$. Avec $r_+\ne r_-$ : $A=(v_0-r_-x_0)/(r_+-r_-)$ et $B=(r_+x_0-v_0)/(r_+-r_-)$. Les deux racines sont négatives pour Q > 0.")+sub('Un exemple résolu',r"$\ddot x+25\dot x+100x=0$ donne $\omega_0=10$ rad/s, Q = 0,40 et les racines -5 et -20 s$^{-1}$. Pour x0 = 3 cm et v0 = 0 : $x=0{,}04e^{-5t}-0{,}01e^{-20t}$ m. La pente initiale est bien nulle.")+sub('Le mode lent',r"La racine la plus proche de zéro domine à long terme si son coefficient n’est pas nul. Ici la constante lente est 0,20 s, la rapide 0,05 s. Le retour ne s’estime pas avec une seule constante sans préciser le domaine temporel.")+box('piege','Coefficients de signes opposés',"La somme peut rester positive alors que l’un des coefficients est négatif. Le signe d’un coefficient n’est pas le signe permanent de la position. Vérifier les valeurs et la dérivée initiales."))
 c.c('Réponse à un échelon constant',r'''Avec une force F0 appliquée à t = 0, $m\ddot x+b\dot x+kx=F_0$. La solution particulière vaut $x_e=F_0/k$. Pour un RLC série sous E constant, $LC\ddot u+RC\dot u+u=E$ et la particulière vaut E.
'''+box('loi','Translater puis résoudre le régime libre',r"Poser X = x - xe ou U = u - E. La variable translatée satisfait l’équation homogène. Pour le RLC déchargé, i(0) = 0 et Q > 1/2 : $u=E\{1-e^{-\alpha t}[\cos\omega_dt+(\alpha/\omega_d)\sin\omega_dt]\}$.")+fig('echelon','La réponse sous-amortie peut dépasser la valeur finale ; au régime critique, ce départ converge sans dépassement.')+sub('Conditions initiales',"La commutation déplace le centre de l’évolution mais ne réinitialise pas les réserves. Déterminer uC(0+) et iL(0+) avec l’état avant la commutation, puis écrire la dérivée initiale u̇C = i/C."))
 c.c('Dépassement et temps du premier pic',box('loi','Cas de l’échelon avec état initial nul',r"Pour Q > 1/2 : le premier maximum est à $t_p=\pi/\omega_d$. Le dépassement relatif est $M_p=(s_{\max}-s_\infty)/s_\infty=e^{-\alpha\pi/\omega_d}$. Ces relations supposent les conditions initiales nulles et le modèle canonique de réponse considéré.")+sub('Démonstration',r"La dérivée de la réponse indicielle réduite vaut $(\omega_0^2/\omega_d)e^{-\alpha t}\sin\omega_dt$. Son premier zéro après le départ est $\pi/\omega_d$. À cette date, le cosinus vaut -1, ce qui donne l’expression du dépassement.")+fig('echelon','La réponse bleue atteint un maximum supérieur à l’asymptote 1, puis revient en oscillant.')+sub('Exemple',r"Pour $\omega_0=1000$ rad/s et Q = 2, $\alpha=250$ s$^{-1}$ et $\omega_d=968{,}25$ rad/s ; $t_p=3{,}245$ ms et $M_p=0{,}4443$. Un échelon de 5 V atteint donc environ 7,22 V au premier pic."))
 c.c('Énergie stockée et énergie perdue',box('loi','Des bilans exacts',r"Mécanique libre : $\mathcal E=mv^2/2+kx^2/2$ et $\dot{\mathcal E}=-bv^2$.\par RLC libre : $\mathcal E=Li^2/2+Cu^2/2$ et $\dot{\mathcal E}=-Ri^2$.\par RLC sous source : $Ei=Ri^2+\dot{\mathcal E}$.")+sub('L’énergie décroît sans être une exponentielle pure',r"Dans le régime libre amorti, les deux réserves continuent à s’échanger. La puissance perdue s’annule aux instants où la vitesse ou le courant s’annule. En général, l’énergie instantanée n’est donc pas exactement $\mathcal E_0e^{-2\alpha t}$.")+sub('Même phase et faible amortissement',r"Deux états séparés de Td sont multipliés par $e^{-\alpha T_d}$ : leurs énergies sont donc dans le rapport exact $e^{-2\alpha T_d}$. Pour un faible amortissement, l’énergie moyennée sur les oscillations est bien décrite par une enveloppe exponentielle.")+box('piege','Le demi-facteur énergétique',r"Le temps d’enveloppe d’amplitude vaut $1/\alpha$ ; celui de l’énergie moyennée vaut $1/(2\alpha)$. Utiliser la même constante dans les deux lois doublerait le temps de décroissance énergétique."))
 c.c('Mesurer Q par le décrément',box('loi','Deux maxima de même signe',r"$\delta=\ln(|x_n|/|x_{n+1}|)=\alpha T_d=2\pi/\sqrt{4Q^2-1}$. Donc $Q=\sqrt{1/4+(\pi/\delta)^2}$. Avec N périodes : $\delta=N^{-1}\ln(|x_n|/|x_{n+N}|)$.")+sub('Retrouver les deux paramètres',r"Mesurer Td donne $\omega_d=2\pi/T_d$. Puis $\alpha=\delta/T_d$ et $\omega_0=\sqrt{\omega_d^2+\alpha^2}$. On en déduit b = 2mα ou R = 2Lα. Les amplitudes doivent être mesurées relativement à l’équilibre, après soustraction de l’offset.")+fig('spirale','La spirale de phase traduit la diminution d’énergie ; les états de même phase se contractent d’un même facteur.')+box('piege','Des pics opposés sont séparés par une demi-période',"Le logarithme de deux valeurs absolues de pics consécutifs de signes opposés ne correspond pas à une période entière. Préciser les dates utilisées et le nombre de cycles."))
 c.c('Combien de temps dure le transitoire ?',box('loi','Le régime impose l’échelle de temps',r"Sous-amorti : enveloppe d’amplitude de constante $\tau_A=2Q/\omega_0$.\par Critique : facteur $(A+Bt)e^{-\omega_0t}$ ; échelle $1/\omega_0$, mais les seuils dépendent aussi du facteur polynomial.\par Apériodique : constante lente $\tau_s=1/(\alpha-\sqrt{\alpha^2-\omega_0^2})$ si le mode correspondant est présent.")+sub('Très fort amortissement',r"Si Q est très petit, la racine lente vaut environ $-Q\omega_0$ et $\tau_s\simeq1/(Q\omega_0)$. Pour le RLC série, cela donne $\tau_s\simeq RC$ ; la constante rapide vaut environ L/R. Augmenter énormément R ralentit donc la queue du transitoire.")+sub('Un critère de seuil',r"Avec $|x|\leq C_0e^{-\alpha t}$, garantir $|x|\leq\varepsilon|x_0|$ demande $t\geq\alpha^{-1}\ln[C_0/(\varepsilon|x_0|)]$. Cette borne est suffisante ; le premier franchissement d’un seuil ne garantit pas qu’il n’y aura plus de dépassement ensuite.")+box('methode','En pratique',"Annoncer un seuil de stabilisation, vérifier la durée de la fenêtre d’acquisition et distinguer le premier passage dans la bande de la date d’entrée définitive dans cette bande."))
 c.c('Confronter le modèle à un relevé',r'''Un bon ajustement doit retrouver les conditions initiales, l’équilibre, la pseudo-période et la décroissance. Des résidus structurés peuvent révéler un modèle incomplet.
'''+sub('Une procédure d’identification',qs("Soustraire l’équilibre et repérer les pics de même signe.",r"Mesurer plusieurs pseudo-périodes ; calculer α et $\omega_0$ avec le décrément.",r"Reconstruire la solution complète avec $B=(v_0+\alpha x_0)/\omega_d$.","Comparer le modèle aux données sur tout l’enregistrement ; examiner les résidus."))+sub('Deux écarts instructifs',"Un frottement solide produit souvent une décroissance d’amplitude plus proche d’une loi affine qu’exponentielle. Dans un circuit, la résistance du GBF ou de la bobine peut modifier Q sans changer les composants de stockage. Ces explications doivent être testées, pas simplement affirmées.")+fig('regimes','Comparer plusieurs formes de transitoire demande de conserver la même normalisation et de préciser les conditions initiales.')+box('methode','Similitude mécanique et électrique',"Comparer les temps réduits ω0t et les amplitudes normalisées pour des valeurs de Q proches. Des paramètres physiques très différents peuvent alors donner les mêmes courbes, dans le domaine de validité des modèles."))
 c.tp_title='Mesurer un amortissement RLC'
 c.tp=fig('rlc','Pour une excitation en échelon, remplacer le fil de gauche par le GBF et conserver sa résistance de sortie dans R.')+qs(r"Choisir L et C puis estimer $\omega_0$ et la résistance critique $R_c=2\sqrt{L/C}$. Mesurer ou estimer la résistance de la bobine.","Observer plusieurs réponses en faisant varier la résistance totale ; repérer les trois régimes.",r"En sous-amorti, relever Td et plusieurs maxima de même signe autour de l’asymptote. Calculer α, Q et R totale.","Comparer au modèle avec la résistance du GBF incluse. Vérifier la cohérence des conditions initiales.","Comparer deux amplitudes d’échelon et examiner si les réponses normalisées se superposent.")+box('docu','Jeu simulé / Pics de même signe',r"Écarts à l’équilibre (V) : $4{,}000$, $2{,}127$, $1{,}131$, $0{,}602$.\par Dates (ms) : $0$, $6{,}315$, $12{,}630$, $18{,}945$.\par Ces valeurs arrondies correspondent à $\omega_0=1000$ rad/s et Q = 5, pas à des mesures réalisées.")
 c.num_title='Intégrer et contrôler l’énergie'
 c.num=r'''On intègre $\dot x=v$, $\dot v=-2\alpha v-\omega_0^2x$ avec un schéma de Runge-Kutta d’ordre 4. Le travail dissipé donne un contrôle indépendant de la simple allure de x(t).
\begin{verbatim}
import numpy as np
w, Q, h = 10.0, 2.0, 0.001
a = w/(2*Q)
t = np.arange(0, 4+h/2, h)
y = np.zeros((len(t), 2)); y[0] = [0.05, 0.0]
def F(z):
    x, v = z
    return np.array([v, -2*a*v-w*w*x])
for n in range(len(t)-1):
    z = y[n]
    k1 = F(z); k2 = F(z+h*k1/2)
    k3 = F(z+h*k2/2); k4 = F(z+h*k3)
    y[n+1] = z+h*(k1+2*k2+2*k3+k4)/6
x, v = y.T
energy = 0.5*(v*v + w*w*x*x)  # par unité de masse
loss_rate = 2*a*v*v
loss = np.r_[0.0, np.cumsum(
    0.5*h*(loss_rate[1:]+loss_rate[:-1]))]
\end{verbatim}
'''+qs(r"Tracer x, puis $\mathcal E(t)+W_{\rm perdu}(t)$ ; vérifier sa constance à l’erreur numérique près.","Diviser le pas par deux. Comparer à la solution analytique et examiner la variation de l’erreur.","Recommencer pour Q = 0,5 et Q = 0,25 ; adapter la durée pour observer le mode lent.")
 c.synthesis=box('loi','L’essentiel',r"$\ddot X+2\alpha\dot X+\omega_0^2X=0$, $\alpha=\omega_0/(2Q)$.\par Q > 1/2 : exponentielle amortie multipliée par sinus et cosinus ; $\omega_d=\sqrt{\omega_0^2-\alpha^2}$.\par Q = 1/2 : $(A+Bt)e^{-\omega_0t}$.\par Q < 1/2 : somme de deux exponentielles réelles.\par Libre : $\dot{\mathcal E}=-bv^2$ ou $-Ri^2$ ; décroissance exacte de l’énergie.\par $\delta=\alpha T_d$ ; $\omega_0^2=\omega_d^2+\alpha^2$.")+sub('À démontrer',qs("L’équation canonique à partir du montage ou des forces.","Les coefficients de la solution pseudo-périodique avec v0 non nulle.","Le bilan d’énergie et le décrément entre maxima de même signe.","La réponse à un échelon par translation de la variable."))+box('docu','Avant de rendre',r"\checkline{R est la résistance totale pertinente.}\checkline{Le régime correspond à Q.}\checkline{Les deux conditions initiales sont satisfaites.}\checkline{La durée annoncée correspond à un seuil explicite.}")
 c.td_titles=['Identifier les paramètres','Classer les régimes','Fixer les constantes','Revenir sans oscillation','Répondre à un échelon','Énergie et décrément','Identifier et comparer','Explorer les limites']
 entries=[
 ('Lire une équation',1,'8 min',qs(r"$\ddot x+4\dot x+100x=0$. Donner $\omega_0$, α, Q et la nature du régime."),r"$\omega_0=10$ rad/s ; α = 2 s$^{-1}$ ; Q = 10/4 = 2,5 > 1/2. Le régime est pseudo-périodique, $\omega_d=\sqrt{96}=9{,}798$ rad/s."),
 ('Une masse freinée',1,'12 min',qs(r"m = 0,20 kg, k = 20 N/m et b = 1 kg/s. Calculer $\omega_0$, α, Q et Td."),r"$\omega_0=10$ rad/s ; α = b/(2m) = 2,5 s$^{-1}$ ; Q = 2 ; $\omega_d=\sqrt{93{,}75}=9{,}6825$ rad/s ; Td = 0,6490 s."),
 ('Un RLC réel',1,'12 min',qs(r"L = 100 mH, C = 1 $\mathrm{\mu F}$. Les résistances sont Rext = 40 Ω, rb = 10 Ω, rg = 50 Ω. Calculer Q et la résistance extérieure critique."),r"Rtot = 100 Ω ; $\omega_0=3162{,}3$ rad/s ; $Q=\sqrt{L/C}/R=3{,}162$. Rtot critique = 632,46 Ω, donc Rext critique = 572,46 Ω. Oublier rb et rg surestimerait Q."),
 ('Trois discriminants',1,'12 min',qs(r"Classer les équations $\ddot x+2\dot x+25x=0$, $\ddot x+10\dot x+25x=0$, $\ddot x+13\dot x+25x=0$. Donner les racines de la dernière."),r"$\omega_0=5$ rad/s dans les trois cas. Les Q sont 2,5 ; 0,5 ; 5/13. Les régimes sont pseudo-périodique, critique puis apériodique. Les dernières racines sont $(-13\pm\sqrt{69})/2$, soit -2,3467 et -10,6533 s$^{-1}$."),
 ('Atteindre le critique',2,'12 min',qs(r"Pour m = 0,50 kg et k = 8 N/m, déterminer le coefficient b critique. Une valeur b = 6 kg/s produit quel régime ?"),r"$b_c=2\sqrt{mk}=4$ kg/s. Avec b = 6 kg/s, Q = 2/6 = 1/3 < 1/2 : régime apériodique. La pulsation propre reste 4 rad/s."),
 ('Comparer deux périodes',2,'12 min',qs(r"Un oscillateur a Q = 1 et $T_0=1$ s. Donner Td et l’écart relatif à T0."),r"$T_d=T_0/\sqrt{1-1/(4Q^2)}=2/\sqrt3=1{,}1547$ s. L’écart relatif est 15,47 %. Identifier directement Td à T0 ne serait pas justifié."),
 ('Libérer sans vitesse',2,'15 min',qs(r"$\omega_0=10$ rad/s, α = 2 s$^{-1}$, x0 = 5 cm, v0 = 0. Donner x(t) et vérifier v(0)."),r"$\omega_d=\sqrt{96}$ ; $x=e^{-2t}[0{,}05\cos(\sqrt{96}t)+(0{,}10/\sqrt{96})\sin(\sqrt{96}t)]$ m. La dérivée initiale vaut $-0{,}10+\sqrt{96}(0{,}10/\sqrt{96})=0$."),
 ('Un lancement non nul',2,'15 min',qs(r"Même équation que E07, mais x0 = 0 et v0 = 0,20 m/s. Déterminer x(t) et sa pente initiale."),r"$x=(0{,}20/\sqrt{96})e^{-2t}\sin(\sqrt{96}t)$ m. x(0) = 0 et v(0) = 0,20 m/s. L’enveloppe a un coefficient 0,02041 m qui n’est pas la position initiale."),
 ('L’erreur du cosinus seul',2,'12 min',qs(r"On propose $x=0{,}03e^{-3t}\cos4t$ pour un départ x0 = 3 cm sans vitesse. Donner la vitesse initiale réelle et corriger le coefficient du sinus."),r"La vitesse initiale proposée est -0,09 m/s. La bonne expression est $x=e^{-3t}(0{,}03\cos4t+0{,}0225\sin4t)$ m ; elle correspond à $\omega_0=5$ rad/s et Q = 5/6."),
 ('Une racine double',2,'15 min',qs(r"$\ddot x+20\dot x+100x=0$, x0 = 2 cm et v0 = 0. Résoudre et donner x à t = 0,10 s."),r"Racine double -10 s$^{-1}$ ; $x=0{,}020(1+10t)e^{-10t}$ m. À 0,10 s, $x=0{,}040/e=1{,}4715$ cm. Le régime est critique."),
 ('Deux exponentielles',2,'18 min',qs(r"$\ddot x+25\dot x+100x=0$, x0 = 3 cm et v0 = 0. Déterminer les racines, la solution et la constante lente."),r"Les racines sont -5 et -20 s$^{-1}$. A + B = 0,03 et -5A -20B = 0 donnent A = 0,04 m, B = -0,01 m. La constante lente est 1/5 = 0,20 s."),
 ('Annuler le mode lent',3,'18 min',qs(r"Pour l’équation de E11 avec x0 = 3 cm, choisir v0 pour que le terme lent disparaisse. Quelle est alors la solution ?"),r"Annuler le coefficient de $e^{-5t}$ impose $v_0=r_-x_0=-20\times0{,}03=-0{,}60$ m/s. Alors $x=0{,}03e^{-20t}$ m. La seule racine la plus lente ne suffit donc pas à connaître la durée si son mode n’est pas excité."),
 ('Un dépassement',2,'15 min',qs(r"Un RLC de $\omega_0=1000$ rad/s et Q = 2 reçoit un échelon de 5 V depuis l’état nul. Calculer le temps du premier pic et la tension maximale."),r"$\alpha=250$ s$^{-1}$ ; $\omega_d=968{,}246$ rad/s. $t_p=\pi/\omega_d=3{,}2446$ ms. $M_p=e^{-\alpha\pi/\omega_d}=0{,}4443$ ; $u_{\max}=5(1+M_p)=7{,}222$ V."),
 ('Un échelon critique',2,'15 min',qs(r"Un système critique de pulsation propre 20 rad/s passe d’un état nul vers une valeur finale S. Donner s(t) et sa pente initiale."),r"$s=S[1-(1+20t)e^{-20t}]$. La pente vaut $400St e^{-20t}$ et s’annule à l’origine. La seconde dérivée initiale vaut $400S$."),
 ('Une capacité déjà chargée',2,'18 min',qs(r"Un RLC reçoit une source constante E, mais uC(0) = U0 et i(0) = I0. En sous-amorti, donner les deux coefficients pour U = uC - E."),r"$U=e^{-\alpha t}(A\cos\omega_dt+B\sin\omega_dt)$, $A=U_0-E$ et $B=[I_0/C+\alpha(U_0-E)]/\omega_d$. Les deux réserves transmettent leur état à la commutation."),
 ('L’énergie aux extrêmes',2,'12 min',qs(r"m = 0,20 kg, k = 20 N/m. Deux maxima positifs successifs valent 5 cm et 3 cm. Calculer la perte d’énergie entre ces instants et le décrément."),r"Aux maxima v = 0 : $\Delta\mathcal E_{\rm perdue}=k(0{,}05^2-0{,}03^2)/2=0{,}016$ J. $\delta=\ln(5/3)=0{,}5108$. La perte est positive tandis que la variation d’énergie du système est négative."),
 ('Déterminer Q',2,'15 min',qs(r"Deux maxima positifs sont dans le rapport 2 et séparés de Td = 0,50 s. Déterminer α, $\omega_d$, $\omega_0$ et Q."),r"$\delta=\ln2$ ; α = δ/Td = 1,3863 s$^{-1}$ ; $\omega_d=4\pi=12{,}566$ rad/s ; $\omega_0=\sqrt{(4\pi)^2+\alpha^2}=12{,}643$ rad/s ; $Q=\sqrt{1/4+(\pi/\ln2)^2}=4{,}560$ environ."),
 ('Des pics opposés',2,'15 min',qs(r"Un maximum de +4 cm est suivi 0,20 s plus tard d’un minimum de -3 cm. Retrouver α et Td dans le modèle sous-amorti. Que donnerait une lecture erronée comme une période entière ?"),r"Les deux extrêmes sont séparés par Td/2 : Td = 0,40 s. α = ln(4/3)/0,20 = 1,4384 s$^{-1}$. L’erreur de période donnerait $\omega_d$ deux fois trop grand ; le décrément par période serait également mal identifié."),
 ('Identifier une résistance',2,'18 min',qs(r"Un RLC série a L = 50 mH, Td = 2,00 ms ; l’amplitude est divisée par e en 10,0 ms. Calculer α, R totale, $\omega_0$ et C."),r"α = 100 s$^{-1}$ ; R = 2Lα = 10 Ω ; $\omega_d=1000\pi$ rad/s ; $\omega_0^2=(1000\pi)^2+10^4$ ; $C=1/(L\omega_0^2)=2{,}024\ \mathrm{\mu F}$ environ."),
 ('Un temps d’enveloppe',2,'15 min',qs(r"$\omega_0=100$ rad/s et Q = 10. Donner la constante d’enveloppe d’amplitude et le temps pour qu’elle soit divisée par 100. Donner la constante de l’énergie moyennée."),r"$\tau_A=2Q/\omega_0=0{,}20$ s ; t = τA ln100 = 0,9210 s. La constante de l’énergie moyennée est 0,10 s. Ces durées portent sur les enveloppes, pas sur le premier zéro du signal."),
 ('Un parallèle différent',3,'20 min',qs(r"Un RLC parallèle libre possède la même tension u sur les trois branches. Établir l’équation et Q. Comment Q dépend-il de R, contrairement au RLC série ?"),r"Loi des nœuds : $C\dot u+u/R+i_L=0$ ; dériver et utiliser $\dot i_L=u/L$ donne $\ddot u+\dot u/(RC)+u/(LC)=0$. $Q=R\sqrt{C/L}$. Augmenter R réduit les pertes parallèles et augmente Q, alors qu’en série Q est inversement proportionnel à R."),
 ('Très grand amortissement',3,'20 min',qs(r"Pour un RLC série fortement apériodique, établir les deux constantes approchées RC et L/R. Application : R = 10 kΩ, L = 1 H, C = 1 $\mathrm{\mu F}$."),r"Pour Q très petit, les racines valent environ $-1/(RC)$ et $-R/L$. Ici Q = 0,10 ; les constantes approchées valent 10 ms et 0,10 ms. Les valeurs exactes sont environ 9,899 ms et 0,1010 ms. Le mode lent peut dominer malgré l’amortissement fort."),
 ('Même Q, mêmes courbes',3,'20 min',qs(r"Deux systèmes ont même Q mais des pulsations propres différentes. En posant θ = ω0t, montrer que leurs réponses réduites peuvent se superposer. Quelles conditions initiales faut-il comparer ?"),r"L’équation devient $\dd^2X/\dd\theta^2+(1/Q)\dd X/\dd\theta+X=0$. Avec une même échelle d’amplitude, comparer X(0) et $(\dot X(0)/\omega_0)$ normalisés. Même Q seul ne garantit pas les mêmes courbes si les conditions réduites diffèrent."),
 ('Un bilan qui détecte une erreur',3,'20 min',qs(r"Un calcul numérique d’un oscillateur libre donne une énergie croissante sur plusieurs cycles malgré b > 0. Est-ce compatible avec le modèle ? Proposer deux contrôles et un moyen de séparer erreur numérique et erreur de modèle."),r"Le modèle impose $\dot{\mathcal E}=-bv^2\leq0$ : une croissance nette n’est pas compatible. Vérifier les signes des forces, puis comparer $\mathcal E(t)+\int_0^t bv^2\dd t$ à sa valeur initiale. Réduire le pas et comparer à la solution exacte ; une dérive qui persiste avec convergence numérique suggère un modèle ou des données incohérents.")]
 for e in entries:c.e(*e)
 c.d('Un cahier des charges sur le dépassement',r"Un système canonique du deuxième ordre, initialement au repos à zéro, reçoit un échelon positif. Il doit osciller mais dépasser sa limite d’au plus 10 %."+qs(r"Traduire la contrainte sur $M_p$ en inégalité sur α/ωd, puis en borne sur Q.",r"La pulsation propre vaut 1000 rad/s. Choisir Q = 0,60 et calculer premier pic et dépassement.",r"Pour un RLC avec L = 100 mH et C = 10 $\mathrm{\mu F}$, calculer R totale qui réalise ce Q.","Expliquer pourquoi la contrainte ne s’applique pas telle quelle à une capacité initialement chargée."),"1. Prendre le logarithme de la formule du dépassement. 2. Utiliser α/ωd = 1/√(4Q²-1). 3. La borne de Q se combine avec Q > 1/2.",r'''$M_p=e^{-\pi/\sqrt{4Q^2-1}}\leq0{,}10$ impose $\pi/\sqrt{4Q^2-1}\geq\ln10$. Donc
\[\frac12<Q\leq\frac12\sqrt{1+(\pi/\ln10)^2}=0{,}846\ \text{environ}.\]
Pour Q = 0,60, α = 833,33 s$^{-1}$ et $\omega_d=552{,}77$ rad/s. $t_p=5{,}683$ ms et $M_p=0{,}00877$, soit 0,877 %. Les composants donnés ont $\omega_0=1000$ rad/s et $\sqrt{L/C}=100\ \Omega$ : R totale = 100/0,60 = 166,67 Ω.
Le dépassement est ici celui de la réponse indicielle avec u(0) = i(0) = 0. Un état initial différent modifie les deux constantes du régime libre et peut produire un autre maximum. Il faut alors repartir de la solution complète.
''')
 c.d('Mesurer un amortissement avec quatre pics',r"Des maxima positifs, mesurés par rapport à un équilibre nul, sont $x_0=4{,}00$ cm, $x_1=2{,}68$ cm, $x_2=1{,}80$ cm et $x_3=1{,}20$ cm aux dates 0 ; 0,50 ; 1,00 ; 1,50 s."+qs(r"Estimer δ à partir des pics extrêmes et retrouver α, $\omega_0$ et Q.",r"La masse vaut 0,20 kg : déterminer k et b.",r"Chaque amplitude extrême a une incertitude-type indépendante de 0,02 cm ; estimer u(δ), en négligeant ici l’incertitude des dates.","Quel contrôle les deux pics intermédiaires permettent-ils ? Que change un offset non soustrait ?"),"1. Diviser le logarithme total par trois périodes. 2. α = δ/Td. 3. Propager les dérivées du logarithme ; un offset ne se comporte pas comme un facteur d’échelle.",r'''$\delta=\ln(4/1{,}2)/3=0{,}40132$ ; α = 0,80265 s$^{-1}$ ; $\omega_d=4\pi$ rad/s ; $\omega_0=\sqrt{(4\pi)^2+\alpha^2}=12{,}592$ rad/s et Q = 7,844 environ.
La raideur vaut $k=m\omega_0^2=31{,}711$ N/m et b = 2mα = 0,3211 kg/s.
\[u(\delta)=\frac13\sqrt{\left(\frac{0{,}02}{4{,}00}\right)^2+\left(\frac{0{,}02}{1{,}20}\right)^2}=0{,}00580.\]
Les pics intermédiaires doivent se placer sur une droite de $\ln|x|$ en fonction du temps, à l’échelle des incertitudes. Ils testent l’hypothèse exponentielle. Un facteur d’étalonnage commun se simplifie dans le rapport, mais un offset déplace surtout les faibles amplitudes et biaise la pente. Les très petits pics ne sont donc pas toujours les meilleurs pour identifier l’amortissement.
''')
 c.d('Un oscillateur très amorti peut être lent',r"Pour un RLC série, on conserve L et C et on augmente R très au-delà du seuil critique."+qs(r"Écrire les racines exactes sous la forme $-R/(2L)\pm\sqrt{(R/(2L))^2-1/(LC)}$.",r"Retrouver les racines approchées à faible Q en rationalisant la racine lente.",r"Pour L = 1 H, C = 1 $\mathrm{\mu F}$, comparer R = 2 kΩ et R = 10 kΩ sur un départ u0 > 0, i0 = 0.",r"Interpréter la séparation des deux durées et expliquer ce que signifie éliminer approximativement l’inductance après le transitoire rapide."),"1. Le critique est R = 2√(L/C). 2. Pour la racine lente, multiplier par le conjugué évite la différence de deux grands nombres. 3. Le courant s’ajuste rapidement, puis la capacité évolue lentement.",r'''Poser $a=R/(2L)$, $\omega_0^2=1/(LC)$. La racine lente est
\[r_s=-a+\sqrt{a^2-\omega_0^2}=-\frac{\omega_0^2}{a+\sqrt{a^2-\omega_0^2}}.\]
Pour a très grand, $r_s\simeq-\omega_0^2/(2a)=-1/(RC)$ et $r_f\simeq-2a=-R/L$. Les constantes sont RC et L/R.
À R = 2 kΩ, le régime est critique : $u/u_0=(1+1000t)e^{-1000t}$. Le seuil 1 % est atteint vers 6,638 ms. À R = 10 kΩ, les constantes exactes valent 9,899 ms et 0,1010 ms ; la queue lente domine et le retour à 1 % demande environ 45,7 ms pour les conditions données.
Le fort amortissement supprime les oscillations mais allonge ici le retour. Après la couche temporelle rapide, on peut négliger $L\ddot u$ devant $R\dot u$ et retrouver une équation RC, à condition de ne pas lui demander de reproduire simultanément les deux conditions initiales du système d’ordre deux.
''')
 c.dm_title='Identifier une bobine réelle'
 c.dm=r"Un RLC série libre utilise C = 2,00 $\mathrm{\mu F}$. Sa tension de capacité possède une pseudo-période Td = 2,00 ms et deux maxima positifs successifs dans le rapport 1,50."+qs(r"Calculer δ, α, $\omega_d$ et $\omega_0$. \textbf{4 points}",r"En déduire L, R totale et Q. \textbf{4 points}",r"La résistance externe vaut 10 Ω et celle du générateur annulé 50 Ω. Estimer la résistance de bobine ; discuter le résultat. \textbf{3 points}",r"Pour uC(0) = 4 V et i(0) = 0, donner uC(t) et i(t) avec des orientations explicites. \textbf{4 points}",r"Donner l’énergie initiale et la fraction perdue entre deux maxima de même signe. \textbf{3 points}",r"Proposer un test expérimental du modèle avec plusieurs maxima. \textbf{2 points}")
 c.dm_sol=sub('1 et 2 / 8 points',r"δ = ln1,5 = 0,40547 ; α = 202,733 s$^{-1}$ ; $\omega_d=1000\pi=3141{,}593$ rad/s et $\omega_0=3148{,}13$ rad/s (4). $L=1/(C\omega_0^2)=50{,}45$ mH ; Rtot = 2Lα = 20,46 Ω ; Q = ω0/(2α) = 7,764 (4).")+sub('3 / 3 points',r"Les valeurs annoncées donneraient rb = 20,46 - 10 - 50 = -39,54 Ω, impossible pour la résistance passive de cette bobine. Les données sont incompatibles avec ce schéma : la résistance de sortie du GBF n’est peut-être pas dans la boucle libre, ou l’une des valeurs est erronée. Ne pas transformer ce résultat en résistance physique négative.")+sub('4 / 4 points',r"Avec i = C du/dt : $u=4e^{-\alpha t}[\cos\omega_dt+(\alpha/\omega_d)\sin\omega_dt]$ et $i=-4C(\omega_0^2/\omega_d)e^{-\alpha t}\sin\omega_dt$. On vérifie u(0) = 4 V et i(0) = 0.")+sub('5 et 6 / 5 points',r"$\mathcal E_0=Cu_0^2/2=16\ \mathrm{\mu J}$. Entre maxima de même signe, le rapport d’énergie est $e^{-2\delta}=1/1{,}5^2=4/9$ ; la fraction perdue vaut 5/9 (3). Ajuster les logarithmes de plusieurs amplitudes en fonction du temps, vérifier l’équilibre et examiner les résidus (2).")
 c.ds_title='Du régime libre au dépassement'
 c.ds=[sub('A / Résoudre un régime libre / 8 points',r"$\ddot x+6\dot x+25x=0$, x(0) = 2 cm, v(0) = 0.")+qs(r"Identifier $\omega_0$, α, Q et le régime. \textbf{2 points}",r"Résoudre en fixant les deux constantes. \textbf{3 points}",r"Donner Td et le décrément entre maxima positifs. \textbf{2 points}",r"Donner une borne exponentielle de |x(t)|. \textbf{1 point}")+sub('B / Circuit et énergie / 6 points',r"Un RLC série possède L = 100 mH, C = 1 $\mathrm{\mu F}$ et R totale = 200 Ω.")+qs(r"Établir l’équation de uC et calculer $\omega_0$, Q et α. \textbf{3 points}",r"Établir le bilan énergétique libre. Pour u0 = 5 V et i0 = 0, donner l’énergie initiale et la dissipation totale. \textbf{3 points}"),sub('C / Réponse indicielle / 6 points',r"Le circuit de B reçoit ensuite un échelon de 5 V depuis un état initial entièrement déchargé et sans courant.")+qs(r"Écrire uC(t), avec les valeurs littérales de α et ωd définies précédemment. \textbf{3 points}",r"Calculer le temps du premier pic et le dépassement relatif. \textbf{2 points}",r"Donner la résistance totale qui rend le système critique. \textbf{1 point}")]
 c.ds_sol=[sub('A / 8 points',r"$\omega_0=5$ rad/s ; α = 3 s$^{-1}$ ; Q = 5/6 ; régime pseudo-périodique avec ωd = 4 rad/s (2). $x=e^{-3t}(0{,}020\cos4t+0{,}015\sin4t)$ m ; la pente initiale vaut -0,060 + 0,060 = 0 (3). Td = π/2 = 1,5708 s et δ = 3π/2 = 4,7124 (2). $|x|\leq0{,}025e^{-3t}$ m (1).")+sub('B / 6 points',r"$LC\ddot u+RC\dot u+u=0$ ; $\omega_0=3162{,}3$ rad/s ; Q = 1,5811 ; α = 1000 s$^{-1}$ (3). En multipliant la maille par i : $\dot{\mathcal E}=-Ri^2$, avec $\mathcal E=Li^2/2+Cu^2/2$. Initialement $\mathcal E_0=12{,}5\ \mathrm{\mu J}$ ; elle est entièrement dissipée à terme (3)."),sub('C / 6 points',r"$\omega_d=\sqrt{10^7-10^6}=3000$ rad/s. $u=5\{1-e^{-1000t}[\cos3000t+(1/3)\sin3000t]\}$ V (3). $t_p=\pi/3000=1{,}0472$ ms ; $M_p=e^{-\pi/3}=0{,}3509$, soit 35,09 % (2). Rcrit = $2\sqrt{L/C}=632{,}46$ Ω (1).")+box('methode','Bilan de correction',"Une solution amortie doit satisfaire les deux conditions initiales. Une résistance critique se compare à la résistance totale. Le dépassement doit être rapporté à la valeur finale, pas au maximum.")]
 c.hints="E09 : dériver le produit exponentielle-cosinus à l’origine. E12 : la condition initiale peut annuler un mode. E17 : utiliser δ/Td pour α puis retrouver ω0. E21 : dériver la loi des nœuds. E22 : rationaliser la racine lente."
 c.eval_hints="Le DM contient volontairement une incohérence à repérer dans la liste des résistances : les mesures doivent être confrontées au schéma. Dans le DS, la partie C reprend les paramètres de B, avec une nouvelle excitation et un nouvel état initial."
 c.source('DS réel / Oscillations amorties','https://cahier-de-prepa.fr/mp*-condorcet/download?id=98&v=66f32','Archive de révision SUP, site MP* Condorcet ; DS5 du 7 janvier 2023 ; problème I, partie II, questions 1, 2, 4 et 5, page PDF 2.',"Prévoir 40 minutes. Mesurer les amplitudes par rapport à l’équilibre, voisin de 10 cm, sur la figure originale. Les valeurs ci-dessous sont des lectures approximatives à affiner avec le graphe.",r"On lit Td ≈ 0,72 s et des premiers pics à environ 15 puis 13,5 cm : les écarts sont 5 et 3,5 cm, d’où δ ≈ ln(5/3,5) = 0,357. Avec m = 0,10 kg et k = 7,78 N/m, $\omega_0\simeq8{,}82$ rad/s, Q ≈ 8,8 et h ≈ 0,10 kg/s. La perte entre ces pics vaut environ $k(0{,}05^2-0{,}035^2)/2\simeq5$ mJ. Pour v0 = 0, conserver le terme sinus de coefficient αX0/ωd dans la solution. La précision est celle d’une lecture graphique, pas d’un ajustement instrumenté.")
 c.source('TD réel / Énergie et qualité','https://mpsi.schleck.ovh/fichiers/td/td5_oscillateurs.pdf','MPSI, schleck.ovh ; TD5 Oscillateurs, année indiquée 2026-2027 ; exercice 4, questions 1 à 7, pages 1/2 et 2/2.',"Prévoir 35 minutes. Le support donne R = 100 Ω, L = 1,00 H, C = 1,00 $\mathrm{\mu F}$. Traiter d’abord la solution exacte puis la simplification de faible amortissement demandée par l’énoncé.",r"$\omega_0=1000$ rad/s et Q = 10 ; α = 50 s$^{-1}$, τA = 0,020 s et $\omega_d=998{,}75$ rad/s. Pour uC(0) = E et i(0) = 0 : A = E et B = αE/ωd dans la forme exacte. Dans l’approximation faible perte, $\mathcal E\simeq CE^2e^{-2t/\tau_A}/2$. La perte relative sur une période vaut alors environ $1-e^{-2\pi/Q}\simeq2\pi/Q$ seulement si $2\pi/Q\ll1$ ; à Q = 10 la dernière linéarisation reste grossière. Entre états exacts de même phase, utiliser $1-e^{-2\alpha T_d}$.")
 c.next="Le chapitre 06 étudiera le régime sinusoïdal forcé, les impédances complexes et la résonance. La pulsation propre et le facteur de qualité resteront les paramètres centraux."
 for n,a,b,tol in [('E02-Td',2*pi/sqrt(93.75),.648924588155778,1e-10),('E03-Rcrit',2*sqrt(.1/1e-6)-60,572.455532033676,1e-10),('E06-Td',1/sqrt(.75),1.1547005383792517,1e-12),('E10-x',.04/exp(1),.014715177646857694,1e-12),('E13-Mp',exp(-pi/sqrt(15)),.4443442250884889,1e-10),('E16-perte',10*(.05**2-.03**2),.016,1e-12),('E17-Q',sqrt(.25+(pi/log(2))**2),4.559856187998019,1e-8),('E19-C',1/(.05*((1000*pi)**2+100**2)),2.02437255e-6,1e-13),('E20-durée',.2*log(100),.9210340371976184,1e-12),('D1-Qmax',.5*sqrt(1+(pi/log(10))**2),.846,0.001),('D2-alpha',log(4/1.2)/1.5,.8026485362172907,1e-12),('D2-k',.2*((4*pi)**2+(log(4/1.2)/1.5)**2),31.71158,.0001),('DM-L',1/(2e-6*((1000*pi)**2+(log(1.5)/.002)**2)),.0504505,.000001),('DS-Mp',exp(-pi/3),.350919807178411,1e-12),('R2-Q',sqrt(1/1e-6)/100,10,1e-12)]:c.check(n,a,b,tol)
 return c
